// This script exports the document history as a spritesheet,
// in guaranteed quality, and supporting transparency,
// as compared with the poor color quality of the GIF export.
// In the future, exporting as APNG might be supported as an official feature,
// which would also allow high quality and transparency in history exports.

// USAGE: paste this code into the browser console

// HACK: Using unnecessary-looking "../src" so that TypeScript can follow the path, but in the browser,
// when pasting this script into the console, it will be relative to the current page's URL, and the ".." will be ignored,
// as there's nothing higher up than "/", assuming the app is hosted at the root of the domain.
// TypeScript still doesn't like the top-level await because there are no exports, but
// exports are not valid in the JS console. So, ignore the errors.
// @ts-ignore
const { write_image_file } = await import("../src/functions.js");
// @ts-ignore
const { make_canvas } = await import("../src/helpers.js");


const width = main_canvas.width;
const height = main_canvas.height;
const frame_history_nodes = [...undos, current_history_node];
const sheet_canvas = make_canvas(width * frame_history_nodes.length, height);
let x = 0;
for (const frame_history_node of frame_history_nodes) {
	sheet_canvas.ctx.clearRect(x, 0, width, height);
	sheet_canvas.ctx.putImageData(frame_history_node.image_data, x, 0);
	x += width;
	if (frame_history_node.selection_image_data) {
		const selection_canvas = make_canvas(frame_history_node.selection_image_data);
		sheet_canvas.ctx.drawImage(selection_canvas, x + frame_history_node.selection_x, frame_history_node.selection_y);
	}
}
write_image_file(sheet_canvas, "image/png", (blob) => {
	const suggested_file_name = `${file_name.replace(/\.(bmp|dib|a?png|gif|jpe?g|jpe|jfif|tiff?|webp|raw)$/i, "")} history animation sheet.png`;
	systemHooks.showSaveFileDialog({
		dialogTitle: localize("Save As"), // localize("Save Animation As"),
		getBlob: () => blob,
		defaultFileName: suggested_file_name,
		defaultPath: typeof system_file_handle === "string" ? `${system_file_handle.replace(/[/\\][^/\\]*/, "")}/${suggested_file_name}` : null,
		defaultFileFormatID: "image/png",
		formats: [{
			formatID: "image/png",
			mimeType: "image/png",
			name: localize("PNG (*.png)").replace(/\s+\([^(]+$/, ""),
			nameWithExtensions: localize("PNG (*.png)"),
			extensions: ["png"],
		}],
	});
});

import { Operation } from 'slate';

import type { YooptaOperation } from './applyTransforms';
import { Blocks } from '../blocks';
import type { SlateElement, YooEditor, YooptaPath } from '../types';

export type HistoryStack = {
  operations: YooptaOperation[];
  path: YooptaPath;
};

export type HistoryStackName = 'undos' | 'redos';

export function inverseEditorOperation(
  editor: YooEditor,
  op: YooptaOperation,
): YooptaOperation | YooptaOperation[] {
  switch (op.type) {
    case 'insert_block':
      return {
        type: 'delete_block',
        path: op.path,
        block: op.block,
      };

    case 'delete_block':
      return {
        type: 'insert_block',
        path: op.path,
        block: op.block,
      };

    case 'set_block_meta': {
      return {
        type: 'set_block_meta',
        id: op.id,
        properties: op.prevProperties,
        prevProperties: op.properties,
      };
    }

    case 'split_block': {
      return [
        {
          type: 'delete_block',
          block: op.properties.nextBlock,
          path: op.path,
        },
        {
          type: 'set_block_value',
          id: op.prevProperties.originalBlock.id,
          value: op.prevProperties.originalValue as SlateElement[],
          forceSlate: true,
        },
      ];
    }

    case 'toggle_block': {
      return {
        type: 'toggle_block',
        properties: {
          toggledBlock: op.prevProperties.sourceBlock,
          toggledSlateValue: op.prevProperties.sourceSlateValue,
        },
        prevProperties: {
          sourceBlock: op.properties.toggledBlock,
          sourceSlateValue: op.properties.toggledSlateValue,
        },
      };
    }

    case 'merge_block': {
      return [
        {
          type: 'split_block',
          properties: {
            nextBlock: op.prevProperties.sourceBlock,
            nextSlateValue: op.prevProperties.sourceSlateValue,
            splitSlateValue: op.prevProperties.targetSlateValue,
          },
          prevProperties: {
            originalBlock: op.properties.mergedBlock,
            originalValue: op.properties.mergedSlateValue,
          },
          path: op.path,
        },
      ];
    }

    case 'move_block': {
      return {
        type: 'move_block',
        properties: op.prevProperties,
        prevProperties: op.properties,
      };
    }

    case 'set_slate': {
      const inverseOps = op.properties.slateOps.map(Operation.inverse).reverse();
      return {
        type: 'set_slate',
        properties: {
          slateOps: inverseOps,
          selectionBefore: op.properties.selectionBefore,
        },
        slate: op.slate,
        blockId: op.blockId,
      };
    }

    case 'set_editor_value': {
      return {
        type: 'set_editor_value',
        properties: op.prevProperties,
        prevProperties: op.properties,
      };
    }

    default:
      return op;
  }
}

export type UndoRedoOptions = {
  scroll?: boolean;
};

export const SAVING = new WeakMap<YooEditor, boolean | undefined>();
export const MERGING = new WeakMap<YooEditor, boolean | undefined>();

export const YooptaHistory = {
  isMergingHistory(editor: YooEditor): boolean | undefined {
    return MERGING.get(editor);
  },

  isSavingHistory(editor: YooEditor): boolean | undefined {
    return SAVING.get(editor);
  },

  withMergingHistory(editor: YooEditor, fn: () => void): void {
    const prev = YooptaHistory.isMergingHistory(editor);
    MERGING.set(editor, true);
    fn();
    MERGING.set(editor, prev);
  },

  withSavingHistory(editor: YooEditor, fn: () => void): void {
    const prev = YooptaHistory.isSavingHistory(editor);
    SAVING.set(editor, true);
    fn();
    SAVING.set(editor, prev);
  },

  withoutMergingHistory(editor: YooEditor, fn: () => void): void {
    const prev = YooptaHistory.isMergingHistory(editor);
    MERGING.set(editor, false);
    fn();
    MERGING.set(editor, prev);
  },

  withoutSavingHistory(editor: YooEditor, fn: () => void): void {
    const prev = YooptaHistory.isSavingHistory(editor);
    SAVING.set(editor, false);
    fn();
    SAVING.set(editor, prev);
  },

  redo: (editor: YooEditor, options?: UndoRedoOptions) => {
    const { redos } = editor.historyStack;

    if (redos.length > 0) {
      const batch = redos[redos.length - 1];

      YooptaHistory.withoutSavingHistory(editor, () => {
        editor.applyTransforms(batch.operations, { source: 'history' });
        editor.setPath(batch.path);

        const { scroll = true } = options || {};
        if (scroll && typeof batch.path.current === 'number') {
          const block = Blocks.getBlock(editor, { at: batch.path.current });

          // [TODO] - not good place to scroll. View tasks should be separated from model tasks
          const blockElement = document.querySelector(`[data-yoopta-block-id="${block?.id}"]`);
          if (blockElement && !isInViewport(blockElement)) {
            blockElement.scrollIntoView({ block: 'center', behavior: 'auto' });
          }
        }
      });

      editor.historyStack.redos.pop();
      editor.historyStack.undos.push(batch);
    }
  },
  undo: (editor: YooEditor, options?: UndoRedoOptions) => {
    const { undos } = editor.historyStack;

    if (undos.length > 0) {
      const batch = editor.historyStack.undos[editor.historyStack.undos.length - 1];

      YooptaHistory.withoutSavingHistory(editor, () => {
        // [TODO] - ask Christopher Nolan to help with this
        const inverseOps = batch.operations
          .flatMap((op) => inverseEditorOperation(editor, op))
          .reverse();
        editor.applyTransforms(inverseOps, { source: 'history' });
        editor.setPath(batch.path);

        const { scroll = true } = options || {};
        if (scroll && typeof batch.path.current === 'number') {
          const block = Blocks.getBlock(editor, { at: batch.path.current });

          // [TODO] - not good place to scroll. View tasks should be separated from model tasks
          const blockElement = document.querySelector(`[data-yoopta-block-id="${block?.id}"]`);
          if (blockElement && !isInViewport(blockElement)) {
            blockElement.scrollIntoView({ block: 'center', behavior: 'auto' });
          }
        }
      });

      editor.historyStack.redos.push(batch);
      editor.historyStack.undos.pop();
    }
  },
};

function isInViewport(element) {
  const rect = element.getBoundingClientRect();
  const html = document.documentElement;
  return (
    rect.top >= 0 &&
    rect.left >= 0 &&
    rect.bottom <= (window.innerHeight || html.clientHeight) &&
    rect.right <= (window.innerWidth || html.clientWidth)
  );
}

// ---------------------------------------------------------------------------
// Stack — past / future transaction lists
// ---------------------------------------------------------------------------

import type { CommittedTransaction, Stack } from "./types";

export interface StackOptions {
  maxDepth?: number;
}

export class StackImpl implements Stack {
  private past: CommittedTransaction[] = [];
  private future: CommittedTransaction[] = [];
  private readonly maxDepth: number;

  constructor(opts?: StackOptions) {
    this.maxDepth = opts?.maxDepth ?? 100;
  }

  // -- public readonly getters (Stack interface) ----------------------------

  get canUndo(): boolean {
    return this.past.length > 0;
  }

  get canRedo(): boolean {
    return this.future.length > 0;
  }

  get undoLabel(): string | null {
    const top = this.past[this.past.length - 1];
    return top ? top.label : null;
  }

  get redoLabel(): string | null {
    const top = this.future[this.future.length - 1];
    return top ? top.label : null;
  }

  get pastCount(): number {
    return this.past.length;
  }

  get futureCount(): number {
    return this.future.length;
  }

  // -- internal mutation methods (used by HistoryImpl) ----------------------

  push(tx: CommittedTransaction, clearsFuture: boolean): void {
    this.past.push(tx);
    if (clearsFuture) {
      this.future.length = 0;
    }
    // evict oldest if over capacity
    while (this.past.length > this.maxDepth) {
      this.past.shift();
    }
  }

  popUndo(): CommittedTransaction | null {
    const tx = this.past.pop() ?? null;
    if (tx) {
      this.future.push(tx);
    }
    return tx;
  }

  popRedo(): CommittedTransaction | null {
    const tx = this.future.pop() ?? null;
    if (tx) {
      this.past.push(tx);
      while (this.past.length > this.maxDepth) {
        this.past.shift();
      }
    }
    return tx;
  }

  /** Remove a specific transaction from whichever list it's in. */
  remove(tx: CommittedTransaction): void {
    let idx = this.past.indexOf(tx);
    if (idx !== -1) {
      this.past.splice(idx, 1);
      return;
    }
    idx = this.future.indexOf(tx);
    if (idx !== -1) {
      this.future.splice(idx, 1);
    }
  }

  /** Move a transaction from past back to future (for redo failure rollback). */
  undoPopRedo(tx: CommittedTransaction): void {
    const idx = this.past.indexOf(tx);
    if (idx !== -1) {
      this.past.splice(idx, 1);
      this.future.push(tx);
    }
  }

  /** Move a transaction from future back to past (for undo failure rollback). */
  undoPopUndo(tx: CommittedTransaction): void {
    const idx = this.future.indexOf(tx);
    if (idx !== -1) {
      this.future.splice(idx, 1);
      this.past.push(tx);
    }
  }

  clear(): void {
    this.past.length = 0;
    this.future.length = 0;
  }
}

// ---------------------------------------------------------------------------
// Transaction — groups Deltas into a single undo/redo step
// ---------------------------------------------------------------------------

import type {
  Delta,
  Transaction,
  TransactionState,
  TransactionOptions,
  CommittedTransaction,
  TransactionOrigin,
} from "./types";

let nextId = 1;

export class TransactionImpl implements Transaction {
  readonly id: string;
  readonly label: string;
  readonly opts: TransactionOptions;

  private _state: TransactionState = "open";
  private _deltas: Delta[] = [];
  private _parent: TransactionImpl | null;

  /** Callback set by History to receive committed result. */
  onCommit: ((tx: CommittedTransaction) => void) | null = null;
  /** Callback set by History to receive error during abort. */
  onError: ((tx: TransactionImpl, error: unknown) => void) | null = null;

  constructor(
    label: string,
    opts: TransactionOptions,
    parent: TransactionImpl | null
  ) {
    this.id = `tx_${nextId++}`;
    this.label = label;
    this.opts = opts;
    this._parent = parent;
  }

  get state(): TransactionState {
    return this._state;
  }

  get deltas(): ReadonlyArray<Delta> {
    return this._deltas;
  }

  get parent(): TransactionImpl | null {
    return this._parent;
  }

  push(delta: Delta): void {
    if (this._state !== "open") {
      throw new Error(
        `Cannot push to ${this._state} transaction "${this.label}"`
      );
    }
    this._deltas.push(delta);
  }

  commit(): void {
    if (this._state !== "open") {
      throw new Error(
        `Cannot commit ${this._state} transaction "${this.label}"`
      );
    }
    this._state = "committed";

    if (this._parent) {
      // Nested: merge deltas into parent
      for (const d of this._deltas) {
        this._parent.push(d);
      }
    } else {
      // Top-level: notify History
      if (this._deltas.length > 0 && this.onCommit) {
        const origin: TransactionOrigin = this.opts.origin ?? {
          type: "local",
        };
        const committed: CommittedTransaction = {
          id: this.id,
          label: this.label,
          deltas: [...this._deltas],
          origin,
          opts: this.opts,
        };
        this.onCommit(committed);
      }
    }
  }

  abort(): void {
    if (this._state !== "open") {
      throw new Error(
        `Cannot abort ${this._state} transaction "${this.label}"`
      );
    }
    this._state = "aborted";

    // Revert in reverse order — best effort
    for (let i = this._deltas.length - 1; i >= 0; i--) {
      try {
        this._deltas[i].revert();
      } catch (err) {
        // Invariant 13: on failure, remaining reverts are skipped
        if (this.onError) {
          this.onError(this, err);
        }
        break;
      }
    }
  }
}

/** Reset the ID counter (for deterministic tests). */
export function __resetTransactionIdCounter(): void {
  nextId = 1;
}

// 字幕历史管理 Zustand Store
import { create } from 'zustand'
import { devtools } from 'zustand/middleware'
import type { SubtitleChunk, SubtitleTranscript } from '@/types/subtitle'
import { normalizeAsrTranscript } from '@/utils/asrTranscriptUtils'
import { logAsrModelOutput } from '@/utils/asrOutputLog'

type ChunkLayer = 'sentence' | 'word'

interface Chunk extends SubtitleChunk {
  deleted?: boolean;
}

interface UpdateAction {
  type: "update";
  layer: ChunkLayer;
  id: string;
  prev: Partial<Chunk>;
  next: Partial<Chunk>;
}

interface BatchUpdateAction {
  type: "batch";
  updates: { layer: ChunkLayer; id: string; prev: Partial<Chunk>; next: Partial<Chunk> }[];
}

interface InsertChunksAction {
  type: "insert";
  chunks: Chunk[]; // 被插入的占位 chunk（撤销时按 id 移除，重做时重新插入）
}

type HistoryAction = UpdateAction | BatchUpdateAction | InsertChunksAction;

interface HistoryState {
  // 字幕数据
  chunks: Chunk[];
  wordChunks: Chunk[];
  hasWordTimestamps: boolean;
  language: string;

  // 历史记录
  undoStack: HistoryAction[];
  redoStack: HistoryAction[];
  lastUpdateTime: number;
  mergeThreshold: number; // 连续操作合并阈值（毫秒）

  // 衍生状态
  text: string; // 所有未删除chunks的text拼接
  duration: number; // 所有未删除chunks的总时长
  canUndo: boolean;
  canRedo: boolean;
}

interface HistoryActions {
  // 基础操作
  setTranscript: (transcript: SubtitleTranscript) => void;
  update: (id: string, next: Partial<Chunk>, layer?: ChunkLayer) => void;
  delete: (id: string) => void; // 封装的删除操作（句子级，级联字词）
  deleteWord: (id: string) => void; // 字词级删除/恢复

  // 历史操作
  undo: () => void;
  redo: () => void;
  clearHistory: () => void;

  // 批量操作
  deleteSelected: (selectedIds: Set<string>) => void;
  restoreSelected: (selectedIds: Set<string>) => void;

  /** 批量设置删除状态（原语言标注/删除模式确认时一次性应用，整批作为一次可撤销操作） */
  setDeletedBatch: (updates: { id: string; deleted: boolean }[]) => void;

  /** 原语言字词级编辑器确认：批量更新字词/空白并同步句子层 */
  confirmOriginalEditorMarks: (plan: {
    wordUpdates: { id: string; deleted: boolean }[];
    blankInserts: { start: number; end: number }[];
    blankUpdates: { id: string; deleted: boolean }[];
  }) => void;

  // 编辑字幕文本
  updateChunkText: (chunkId: string, newText: string) => void;

  // 批量更新多个 chunk 的 text/secondText（整批作为一次 undo）
  batchUpdateText: (updates: { id: string; text?: string; secondText?: string }[]) => void;

  // 智能剪切：插入空白占位 chunk（deleted:true），作为一次可撤销操作
  insertBlankChunks: (segments: { start: number; end: number }[]) => void;

  // 重置
  reset: () => void;
}

// 计算衍生状态的辅助函数
const computeDerivedState = (chunks: Chunk[]) => {
  const activeChunks = chunks.filter(chunk => !chunk.deleted);

  const text = activeChunks
    .sort((a, b) => a.timestamp[0] - b.timestamp[0])
    .map(chunk => chunk.text)
    .join(' ');

  const duration = activeChunks.reduce((total, chunk) => {
    return total + (chunk.timestamp[1] - chunk.timestamp[0]);
  }, 0);

  return { text, duration };
};

// 初始状态
const applyChunkUpdate = (
  chunks: Chunk[],
  wordChunks: Chunk[],
  layer: ChunkLayer,
  id: string,
  patch: Partial<Chunk>,
): { chunks: Chunk[]; wordChunks: Chunk[] } => {
  if (layer === 'word') {
    const index = wordChunks.findIndex((chunk) => chunk.id === id);
    if (index === -1) return { chunks, wordChunks };
    const nextWordChunks = [...wordChunks];
    nextWordChunks[index] = { ...nextWordChunks[index], ...patch };
    return { chunks, wordChunks: nextWordChunks };
  }

  const index = chunks.findIndex((chunk) => chunk.id === id);
  if (index === -1) return { chunks, wordChunks };
  const nextChunks = [...chunks];
  nextChunks[index] = { ...nextChunks[index], ...patch };
  return { chunks: nextChunks, wordChunks };
};

const syncSentenceFromWords = (chunks: Chunk[], wordChunks: Chunk[], sentenceId: string): Chunk[] => {
  const sentence = chunks.find((chunk) => chunk.id === sentenceId);
  if (!sentence?.wordIds?.length) return chunks;

  const words = sentence.wordIds
    .map((wordId) => wordChunks.find((word) => word.id === wordId))
    .filter((word): word is Chunk => Boolean(word));
  if (words.length === 0) return chunks;

  const activeWords = words.filter((word) => !word.deleted);
  const allDeleted = activeWords.length === 0;
  // 与 groupWordsIntoSentences 一致：字词直接拼接（中文无空格）
  const text = allDeleted
    ? sentence.text
    : activeWords.map((word) => word.text).join('').trim() || sentence.text;
  const timestamp: [number, number] = allDeleted
    ? sentence.timestamp
    : [
      Math.min(...activeWords.map((word) => word.timestamp[0])),
      Math.max(...activeWords.map((word) => word.timestamp[1])),
    ];

  return chunks.map((chunk) =>
    chunk.id === sentenceId
      ? { ...chunk, deleted: allDeleted, text, timestamp }
      : chunk,
  );
};

const initialState: HistoryState = {
  chunks: [],
  wordChunks: [],
  hasWordTimestamps: false,
  language: 'en',
  undoStack: [],
  redoStack: [],
  lastUpdateTime: 0,
  mergeThreshold: 500,
  text: '',
  duration: 0,
  canUndo: false,
  canRedo: false,
};

// 创建Store
export const useHistoryStore = create<HistoryState & HistoryActions>()(
  devtools(
    (set, get) => ({
      ...initialState,

      // 设置字幕转录内容
      setTranscript: (transcript) => {
        logAsrModelOutput(transcript, {
          source: 'setTranscript',
          stage: '模型原始输出',
        });

        const normalized = normalizeAsrTranscript(transcript);

        logAsrModelOutput(normalized, {
          source: 'setTranscript',
          stage: '规范化后',
        });
        const chunks = normalized.chunks.map((chunk) => ({
          ...chunk,
          deleted: chunk.deleted ?? false,
        }));
        const wordChunks = (normalized.wordChunks ?? []).map((chunk) => ({
          ...chunk,
          deleted: chunk.deleted ?? false,
        }));
        const derived = computeDerivedState(chunks);

        set({
          chunks,
          wordChunks,
          hasWordTimestamps: normalized.hasWordTimestamps ?? false,
          language: normalized.language,
          text: derived.text,
          duration: derived.duration,
          undoStack: [],
          redoStack: [],
          canUndo: false,
          canRedo: false,
        });
      },

      // 更新 chunk 属性（句子或字词层）
      update: (id, next, layer = 'sentence') => {
        const state = get();
        const sourceChunks = layer === 'word' ? state.wordChunks : state.chunks;
        const chunk = sourceChunks.find((item) => item.id === id);
        if (!chunk) return;

        const prev: Partial<Chunk> = {};
        for (const key in next) {
          const k = key as keyof Chunk;
          prev[k] = chunk[k] as never;
        }

        const now = Date.now();
        const lastAction = state.undoStack[state.undoStack.length - 1];
        const applied = applyChunkUpdate(state.chunks, state.wordChunks, layer, id, next);
        let newChunks = applied.chunks;
        const newWordChunks = applied.wordChunks;

        if (layer === 'word' && chunk.sentenceId) {
          newChunks = syncSentenceFromWords(newChunks, newWordChunks, chunk.sentenceId);
        }

        let newUndoStack: HistoryAction[];
        const newRedoStack: HistoryAction[] = [];
        const newLastUpdateTime = now;

        if (
          lastAction &&
          lastAction.type === 'update' &&
          lastAction.layer === layer &&
          lastAction.id === id &&
          now - state.lastUpdateTime < state.mergeThreshold
        ) {
          const mergedAction = {
            ...lastAction,
            next: { ...lastAction.next, ...next },
          };
          newUndoStack = [...state.undoStack.slice(0, -1), mergedAction];
        } else {
          const action: UpdateAction = { type: 'update', layer, id, prev, next };
          newUndoStack = [...state.undoStack, action];
        }

        const derived = computeDerivedState(newChunks);

        set({
          chunks: newChunks,
          wordChunks: newWordChunks,
          undoStack: newUndoStack,
          redoStack: newRedoStack,
          lastUpdateTime: newLastUpdateTime,
          text: derived.text,
          duration: derived.duration,
          canUndo: newUndoStack.length > 0,
          canRedo: newRedoStack.length > 0,
        });
      },

      // 删除句子（有字词时级联到 wordChunks）
      delete: (id) => {
        const state = get();
        const chunk = state.chunks.find((item) => item.id === id);
        if (!chunk) return;

        const nextDeleted = !chunk.deleted;
        if (state.hasWordTimestamps && chunk.wordIds?.length) {
          const updates: BatchUpdateAction['updates'] = [
            {
              layer: 'sentence',
              id,
              prev: { deleted: chunk.deleted },
              next: { deleted: nextDeleted },
            },
          ];

          for (const wordId of chunk.wordIds) {
            const word = state.wordChunks.find((item) => item.id === wordId);
            if (!word) continue;
            updates.push({
              layer: 'word',
              id: wordId,
              prev: { deleted: word.deleted },
              next: { deleted: nextDeleted },
            });
          }

          let newChunks = [...state.chunks];
          let newWordChunks = [...state.wordChunks];
          for (const item of updates) {
            const applied = applyChunkUpdate(
              newChunks,
              newWordChunks,
              item.layer,
              item.id,
              item.next,
            );
            newChunks = applied.chunks;
            newWordChunks = applied.wordChunks;
          }

          const derived = computeDerivedState(newChunks);
          set({
            chunks: newChunks,
            wordChunks: newWordChunks,
            undoStack: [...state.undoStack, { type: 'batch', updates }],
            redoStack: [],
            text: derived.text,
            duration: derived.duration,
            canUndo: true,
            canRedo: false,
          });
          return;
        }

        get().update(id, { deleted: nextDeleted }, 'sentence');
      },

      deleteWord: (id) => {
        const state = get();
        const word = state.wordChunks.find((item) => item.id === id);
        if (!word) return;
        get().update(id, { deleted: !word.deleted }, 'word');
      },

      // 撤销操作
      undo: () => {
        const state = get();
        if (state.undoStack.length === 0) return;

        const action = state.undoStack[state.undoStack.length - 1];
        let newChunks = [...state.chunks];
        let newWordChunks = [...state.wordChunks];

        if (action.type === "update") {
          const applied = applyChunkUpdate(
            newChunks,
            newWordChunks,
            action.layer,
            action.id,
            action.prev,
          );
          newChunks = applied.chunks;
          newWordChunks = applied.wordChunks;
          if (action.layer === 'word') {
            const word = newWordChunks.find((item) => item.id === action.id);
            if (word?.sentenceId) {
              newChunks = syncSentenceFromWords(newChunks, newWordChunks, word.sentenceId);
            }
          }
        } else if (action.type === "batch") {
          for (const u of action.updates) {
            const applied = applyChunkUpdate(
              newChunks,
              newWordChunks,
              u.layer,
              u.id,
              u.prev,
            );
            newChunks = applied.chunks;
            newWordChunks = applied.wordChunks;
          }
        } else {
          // insert: 撤销时移除被插入的占位 chunk
          const insertedIds = new Set(action.chunks.map(c => c.id));
          for (let i = newChunks.length - 1; i >= 0; i--) {
            if (insertedIds.has(newChunks[i].id)) {
              newChunks.splice(i, 1);
            }
          }
        }

        // 移动到redo栈
        const newUndoStack = state.undoStack.slice(0, -1);
        const newRedoStack = [...state.redoStack, action];

        // 重新计算衍生状态
        const derived = computeDerivedState(newChunks);

        set({
          chunks: newChunks,
          wordChunks: newWordChunks,
          undoStack: newUndoStack,
          redoStack: newRedoStack,
          text: derived.text,
          duration: derived.duration,
          canUndo: newUndoStack.length > 0,
          canRedo: newRedoStack.length > 0,
        });
      },

      // 重做操作
      redo: () => {
        const state = get();
        if (state.redoStack.length === 0) return;

        const action = state.redoStack[state.redoStack.length - 1];
        let newChunks = [...state.chunks];
        let newWordChunks = [...state.wordChunks];

        if (action.type === "update") {
          const applied = applyChunkUpdate(
            newChunks,
            newWordChunks,
            action.layer,
            action.id,
            action.next,
          );
          newChunks = applied.chunks;
          newWordChunks = applied.wordChunks;
          if (action.layer === 'word') {
            const word = newWordChunks.find((item) => item.id === action.id);
            if (word?.sentenceId) {
              newChunks = syncSentenceFromWords(newChunks, newWordChunks, word.sentenceId);
            }
          }
        } else if (action.type === "batch") {
          for (const u of action.updates) {
            const applied = applyChunkUpdate(
              newChunks,
              newWordChunks,
              u.layer,
              u.id,
              u.next,
            );
            newChunks = applied.chunks;
            newWordChunks = applied.wordChunks;
          }
        } else {
          // insert: 重做时重新插入占位 chunk，按时间顺序合并
          const existingIds = new Set(newChunks.map(c => c.id));
          const toInsert = action.chunks.filter(c => !existingIds.has(c.id));
          if (toInsert.length > 0) {
            newChunks.push(...toInsert);
            newChunks.sort((a, b) => a.timestamp[0] - b.timestamp[0]);
          }
        }

        // 移动回undo栈
        const newUndoStack = [...state.undoStack, action];
        const newRedoStack = state.redoStack.slice(0, -1);

        // 重新计算衍生状态
        const derived = computeDerivedState(newChunks);

        set({
          chunks: newChunks,
          wordChunks: newWordChunks,
          undoStack: newUndoStack,
          redoStack: newRedoStack,
          text: derived.text,
          duration: derived.duration,
          canUndo: newUndoStack.length > 0,
          canRedo: newRedoStack.length > 0,
        });
      },

      // 清空历史记录
      clearHistory: () => {
        set({
          undoStack: [],
          redoStack: [],
          canUndo: false,
          canRedo: false,
        });
      },

      // 批量删除选中的 chunks（有字词时间戳时级联到 wordChunks，保证导出裁剪与原语言删除线一致）
      deleteSelected: (selectedIds) => {
        const state = get();
        const batchUpdates: BatchUpdateAction['updates'] = [];
        let newChunks = [...state.chunks];
        let newWordChunks = [...state.wordChunks];
        const now = Date.now();

        for (const id of selectedIds) {
          const chunkIndex = newChunks.findIndex((c) => c.id === id);
          if (chunkIndex === -1) continue;
          const chunk = newChunks[chunkIndex];
          if (chunk.deleted) continue;

          batchUpdates.push({
            layer: 'sentence',
            id,
            prev: { deleted: chunk.deleted },
            next: { deleted: true },
          });
          newChunks[chunkIndex] = { ...chunk, deleted: true };

          if (state.hasWordTimestamps && chunk.wordIds?.length) {
            for (const wordId of chunk.wordIds) {
              const word = newWordChunks.find((item) => item.id === wordId);
              if (!word || word.deleted) continue;
              batchUpdates.push({
                layer: 'word',
                id: wordId,
                prev: { deleted: word.deleted },
                next: { deleted: true },
              });
              const applied = applyChunkUpdate(newChunks, newWordChunks, 'word', wordId, {
                deleted: true,
              });
              newChunks = applied.chunks;
              newWordChunks = applied.wordChunks;
            }
          }
        }

        if (batchUpdates.length === 0) return;

        const derived = computeDerivedState(newChunks);
        set({
          chunks: newChunks,
          wordChunks: newWordChunks,
          undoStack: [...state.undoStack, { type: 'batch', updates: batchUpdates }],
          redoStack: [],
          lastUpdateTime: now,
          text: derived.text,
          duration: derived.duration,
          canUndo: true,
          canRedo: false,
        });
      },

      // 批量恢复选中的 chunks（同步恢复级联的 wordChunks）
      restoreSelected: (selectedIds) => {
        const state = get();
        const batchUpdates: BatchUpdateAction['updates'] = [];
        let newChunks = [...state.chunks];
        let newWordChunks = [...state.wordChunks];
        const now = Date.now();

        for (const id of selectedIds) {
          const chunkIndex = newChunks.findIndex((c) => c.id === id);
          if (chunkIndex === -1) continue;
          const chunk = newChunks[chunkIndex];
          if (!chunk.deleted) continue;

          batchUpdates.push({
            layer: 'sentence',
            id,
            prev: { deleted: chunk.deleted },
            next: { deleted: false },
          });
          newChunks[chunkIndex] = { ...chunk, deleted: false };

          if (state.hasWordTimestamps && chunk.wordIds?.length) {
            for (const wordId of chunk.wordIds) {
              const word = newWordChunks.find((item) => item.id === wordId);
              if (!word || !word.deleted) continue;
              batchUpdates.push({
                layer: 'word',
                id: wordId,
                prev: { deleted: word.deleted },
                next: { deleted: false },
              });
              const applied = applyChunkUpdate(newChunks, newWordChunks, 'word', wordId, {
                deleted: false,
              });
              newChunks = applied.chunks;
              newWordChunks = applied.wordChunks;
            }
          }
        }

        if (batchUpdates.length === 0) return;

        const derived = computeDerivedState(newChunks);
        set({
          chunks: newChunks,
          wordChunks: newWordChunks,
          undoStack: [...state.undoStack, { type: 'batch', updates: batchUpdates }],
          redoStack: [],
          lastUpdateTime: now,
          text: derived.text,
          duration: derived.duration,
          canUndo: true,
          canRedo: false,
        });
      },

      confirmOriginalEditorMarks: (plan) => {
        const state = get();
        if (
          plan.wordUpdates.length === 0
          && plan.blankInserts.length === 0
          && plan.blankUpdates.length === 0
        ) {
          return;
        }

        let newChunks = [...state.chunks];
        let newWordChunks = [...state.wordChunks];
        const batchUpdates: BatchUpdateAction['updates'] = [];
        const insertedBlanks: Chunk[] = [];
        const affectedSentenceIds = new Set<string>();

        for (const update of plan.wordUpdates) {
          const word = newWordChunks.find((item) => item.id === update.id);
          if (!word || word.deleted === update.deleted) continue;
          batchUpdates.push({
            layer: 'word',
            id: update.id,
            prev: { deleted: word.deleted },
            next: { deleted: update.deleted },
          });
          const applied = applyChunkUpdate(newChunks, newWordChunks, 'word', update.id, {
            deleted: update.deleted,
          });
          newChunks = applied.chunks;
          newWordChunks = applied.wordChunks;
          if (word.sentenceId) affectedSentenceIds.add(word.sentenceId);
        }

        for (const update of plan.blankUpdates) {
          const chunkIndex = newChunks.findIndex((chunk) => chunk.id === update.id);
          if (chunkIndex === -1) continue;
          const chunk = newChunks[chunkIndex];
          if (chunk.deleted === update.deleted) continue;
          batchUpdates.push({
            layer: 'sentence',
            id: update.id,
            prev: { deleted: chunk.deleted },
            next: { deleted: update.deleted },
          });
          newChunks[chunkIndex] = { ...chunk, deleted: update.deleted };
        }

        const existingIds = new Set(newChunks.map((chunk) => chunk.id));
        for (const seg of plan.blankInserts) {
          const id = `blank-${seg.start.toFixed(3)}-${seg.end.toFixed(3)}`;
          if (existingIds.has(id)) continue;
          const blankChunk: Chunk = {
            id,
            text: '',
            timestamp: [seg.start, seg.end],
            deleted: true,
            isBlankSpacer: true,
          };
          insertedBlanks.push(blankChunk);
          existingIds.add(id);
        }

        if (insertedBlanks.length > 0) {
          newChunks = [...newChunks, ...insertedBlanks].sort(
            (a, b) => a.timestamp[0] - b.timestamp[0],
          );
        }

        for (const sentenceId of affectedSentenceIds) {
          newChunks = syncSentenceFromWords(newChunks, newWordChunks, sentenceId);
        }

        const actions: HistoryAction[] = [];
        if (batchUpdates.length > 0) {
          actions.push({ type: 'batch', updates: batchUpdates });
        }
        if (insertedBlanks.length > 0) {
          actions.push({ type: 'insert', chunks: insertedBlanks });
        }
        if (actions.length === 0) return;

        const derived = computeDerivedState(newChunks);
        set({
          chunks: newChunks,
          wordChunks: newWordChunks,
          undoStack: [...state.undoStack, ...actions],
          redoStack: [],
          lastUpdateTime: Date.now(),
          text: derived.text,
          duration: derived.duration,
          canUndo: true,
          canRedo: false,
        });
      },

      // 批量设置删除状态（句子级；有字词时级联到 wordChunks）
      setDeletedBatch: (updates) => {
        const state = get();
        if (updates.length === 0) return;
        let newChunks = [...state.chunks];
        let newWordChunks = [...state.wordChunks];
        const now = Date.now();
        const batchUpdates: BatchUpdateAction['updates'] = [];

        for (const u of updates) {
          const chunkIndex = newChunks.findIndex(c => c.id === u.id);
          if (chunkIndex === -1) continue;
          const chunk = newChunks[chunkIndex];
          if (chunk.isBlankSpacer) continue; // 空白占位段不参与标注/删除模式
          if (chunk.deleted === u.deleted) continue;
          const prev: Partial<Chunk> = { deleted: chunk.deleted };
          const next: Partial<Chunk> = { deleted: u.deleted };
          batchUpdates.push({ layer: 'sentence', id: u.id, prev, next });
          newChunks[chunkIndex] = { ...chunk, deleted: u.deleted };

          if (state.hasWordTimestamps && chunk.wordIds?.length) {
            for (const wordId of chunk.wordIds) {
              const word = newWordChunks.find((item) => item.id === wordId);
              if (!word || word.deleted === u.deleted) continue;
              batchUpdates.push({
                layer: 'word',
                id: wordId,
                prev: { deleted: word.deleted },
                next: { deleted: u.deleted },
              });
              const applied = applyChunkUpdate(newChunks, newWordChunks, 'word', wordId, {
                deleted: u.deleted,
              });
              newChunks = applied.chunks;
              newWordChunks = applied.wordChunks;
            }
          }
        }

        if (batchUpdates.length === 0) return;

        const action: BatchUpdateAction = { type: "batch", updates: batchUpdates };
        const derived = computeDerivedState(newChunks);

        set({
          chunks: newChunks,
          wordChunks: newWordChunks,
          undoStack: [...state.undoStack, action],
          redoStack: [],
          lastUpdateTime: now,
          text: derived.text,
          duration: derived.duration,
          canUndo: true,
          canRedo: false,
        });
      },

      // 编辑字幕文本
      updateChunkText: (chunkId, newText) => {
        const state = get();
        const newChunks = [...state.chunks];
        const now = Date.now();

        const chunkIndex = newChunks.findIndex(c => c.id === chunkId);
        if (chunkIndex === -1) {
          console.warn('找不到指定的字幕片段:', chunkId);
          return;
        }

        const chunk = newChunks[chunkIndex];
        const trimmedText = newText.trim();

        // 如果文本没有变化，不需要更新
        if (chunk.text === trimmedText) {
          return;
        }

        const action: UpdateAction = {
          type: "update",
          layer: 'sentence',
          id: chunkId,
          prev: { text: chunk.text },
          next: { text: trimmedText }
        };

        // 更新chunk文本
        newChunks[chunkIndex] = { ...chunk, text: trimmedText };

        // 重新计算衍生状态
        const derived = computeDerivedState(newChunks);

        set({
          chunks: newChunks,
          undoStack: [...state.undoStack, action],
          redoStack: [],
          lastUpdateTime: now,
          text: derived.text,
          duration: derived.duration,
          canUndo: true,
          canRedo: false,
        });
      },

      // 批量更新多个 chunk 的 text/secondText（整批作为一次 undo）
      batchUpdateText: (updates) => {
        const state = get();
        if (updates.length === 0) return;
        const newChunks = [...state.chunks];
        const now = Date.now();
        const batchUpdates: BatchUpdateAction['updates'] = [];

        for (const u of updates) {
          const chunkIndex = newChunks.findIndex(c => c.id === u.id);
          if (chunkIndex === -1) continue;
          const chunk = newChunks[chunkIndex];
          const next: Partial<Chunk> = {};
          const prev: Partial<Chunk> = {};
          if (u.text !== undefined && u.text !== chunk.text) {
            next.text = u.text;
            prev.text = chunk.text;
          }
          if (u.secondText !== undefined && u.secondText !== chunk.secondText) {
            next.secondText = u.secondText;
            prev.secondText = chunk.secondText;
          }
          if (Object.keys(next).length === 0) continue;
          batchUpdates.push({ layer: 'sentence', id: u.id, prev, next });
          newChunks[chunkIndex] = { ...chunk, ...next };
        }

        if (batchUpdates.length === 0) return;

        const action: BatchUpdateAction = { type: "batch", updates: batchUpdates };
        const derived = computeDerivedState(newChunks);

        set({
          chunks: newChunks,
          undoStack: [...state.undoStack, action],
          redoStack: [],
          lastUpdateTime: now,
          text: derived.text,
          duration: derived.duration,
          canUndo: true,
          canRedo: false,
        });
      },

      // 智能剪切：插入空白占位 chunk
      insertBlankChunks: (segments) => {
        const state = get();
        if (segments.length === 0) return;

        // 跳过已存在的同 id 占位 chunk，避免重复插入
        const existingIds = new Set(state.chunks.map(c => c.id));
        const newBlankChunks: Chunk[] = [];
        for (const seg of segments) {
          const id = `blank-${seg.start.toFixed(3)}-${seg.end.toFixed(3)}`;
          if (existingIds.has(id)) continue;
          newBlankChunks.push({
            id,
            text: '',
            timestamp: [seg.start, seg.end],
            deleted: true,
            isBlankSpacer: true,
          });
        }

        if (newBlankChunks.length === 0) return;

        const newChunks = [...state.chunks, ...newBlankChunks];
        newChunks.sort((a, b) => a.timestamp[0] - b.timestamp[0]);

        const action: InsertChunksAction = { type: "insert", chunks: newBlankChunks };
        const derived = computeDerivedState(newChunks);

        set({
          chunks: newChunks,
          undoStack: [...state.undoStack, action],
          redoStack: [],
          lastUpdateTime: Date.now(),
          text: derived.text,
          duration: derived.duration,
          canUndo: true,
          canRedo: false,
        });
      },

      // 重置所有状态
      reset: () => {
        set(initialState);
      },
    }),
    {
      name: 'history-store', // Redux DevTools
    }
  )
);

